const express = require("express");

const app = express();
app.use(express.json());

const rooms = [
  { id: 1, name: "Lab A", capacity: 24 },
  { id: 2, name: "Studio B", capacity: 18 },
];

app.patch("/api/rooms/:id", (req, res) => {
  const id = Number(req.params.id);
  const room = rooms.find((item) => item.id === id);

  if (!room) {
    return res.status(404).json({ error: "Room not found" });
  }

  if (req.body.name !== undefined) {
    room.name = req.body.name;
  }

  if (req.body.capacity !== undefined) {
    room.capacity = req.body.capacity;
  }

  return res.status(200).json(room);
});

app.listen(3000, "127.0.0.1", () => {
  console.log("API listening on http://127.0.0.1:3000");
});

sketchBlocks.bodyMarkdown:
DELETE should remove exactly one identified resource.

```js
app.delete("/api/events/:id", (req, res) => {
  const id = Number(req.params.id);
  const index = events.findIndex((item) => item.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Event not found" });
  }

  events.splice(index, 1);
  return res.status(204).send();
});
```

**Step by step:** normalize the id, locate the array index, stop on the missing sentinel, remove one item, and send an intentional no-content success response.

